/* Photographic hangers rotate about their measured hook contact points. */
window.initShadesHero=function(){
 const old=document.querySelector('.hero');if(!old)return;document.body.classList.add('rail-home');
 const pieces=P.filter(p=>p.rail),reduced=matchMedia('(prefers-reduced-motion: reduce)'),touch=matchMedia('(hover: none), (max-width: 760px)');
 // The reference's cubic-bezier(0.22, 1, 0.36, 1), without an extra easing library.
 const cinematic=t=>{let u=t;for(let n=0;n<6;n++){const x=.66*u-.24*u*u+.58*u*u*u,dx=.66-.48*u+1.74*u*u;u=Math.max(0,Math.min(1,u-(x-t)/dx));}return 1-Math.pow(1-u,3);};
 old.outerHTML=`<section class="rail-hero" aria-label="SHADES menswear exhibition"><div class="rail-heading"><span class="rail-kicker">NEW COLLECTION <i></i> EVENING & TAILORING</span><h1>Silhouettes that <em>hang right.</em></h1></div><div class="rail-scene" tabindex="0" role="region" aria-label="Menswear clothesline. Drag or swipe to browse, use arrow keys to select, Enter to look closer." aria-describedby="rail-help"><div class="rail-camera"><svg class="rail-rope" aria-hidden="true"><defs><pattern id="rope-fiber" width="7" height="7" patternUnits="userSpaceOnUse" patternTransform="rotate(28)"><rect width="7" height="7" fill="#ac9873"/><path d="M0 1h7M0 4h7" stroke="#ddd0ad" stroke-width=".7"/><path d="M0 6h7" stroke="#867554" stroke-width=".6"/></pattern></defs><path class="rope-shadow"/><path class="rope-body"/><path class="rope-highlight"/></svg><div class="rail-pieces"></div></div></div><div class="rail-bottom"><p id="rail-help"><span aria-hidden="true"></span><b></b></p><div class="rail-browser"><button type="button" data-step="-1" aria-label="Previous piece">Previous</button><span class="rail-track"><i></i></span><button type="button" data-step="1" aria-label="Next piece">Next</button></div><div class="rail-statement"><p>Considered cloth. A natural presence.<br>Pieces made to move with you.</p><a href="shop.html">Explore the collection</a></div></div><p class="sr-only" role="status" id="rail-announcement"></p></section>`;
 const hero=document.querySelector('.rail-hero'),scene=hero.querySelector('.rail-scene'),camera=hero.querySelector('.rail-camera'),rack=hero.querySelector('.rail-pieces'),heading=hero.querySelector('.rail-heading');
 const moneyTag=n=>'₹'+(n/1000).toFixed(n%1000?1:0)+'k';
 rack.innerHTML=pieces.map((p,i)=>`<button type="button" class="rail-piece" data-piece="${i}" aria-label="Look closer at ${p.name}, ${money(p.price)}" tabindex="${i===0?0:-1}"><span class="rail-rig"><img class="rail-photo" src="${p.views.front}" width="${p.imageWidth}" height="${p.imageHeight}" alt="${p.name} on a walnut hanger" decoding="async" ${i<6?'fetchpriority="high"':''}></span><span class="rail-price" aria-hidden="true">${moneyTag(p.price)}</span><span class="rail-label" aria-hidden="true"><strong>${p.name}</strong><span>${money(p.price)}</span><small>VIEW DETAILS</small></span></button>`).join('');
 const nodes=[...rack.children],states=pieces.map(()=>({swing:0,velocity:0,scale:1,scaleVelocity:0,depth:0,depthVelocity:0})),motion={offset:0,pan:0,phase:0};let active=-1,keyIndex=touch.matches?0:5,drag=null,suppress=false,frame=0,last=0,visible=true,showroom=null,entry=null,wind=null,entryFinished=false;
 const help=()=>hero.querySelector('#rail-help b').textContent=touch.matches?'Swipe the rail · tap a piece to look closer':'Hover a piece · click to look closer';help();touch.addEventListener('change',help);
 function stepSize(){return touch.matches?Math.max(178,scene.clientWidth*.47):Math.max(125,scene.clientWidth/11)}
 function ropeY(x){const w=scene.clientWidth;return scene.clientHeight*.25+38*(1-Math.pow(2*x/w-1,2))}
 function paint(){const w=scene.clientWidth,h=scene.clientHeight,step=stepSize(),total=step*pieces.length,base=h*.25,sag=38;
  hero.querySelectorAll('.rail-rope path').forEach(path=>path.setAttribute('d',`M0 ${base} Q${w/2} ${base+sag*2} ${w} ${base}`));
  nodes.forEach((node,i)=>{let x=w/2+(i-(touch.matches?0:5.5))*step-motion.offset+motion.pan;const start=(w-total)/2;x=((x-start)%total+total)%total+start;const p=pieces[i],s=states[i],height=Math.min(h*(touch.matches?.53:.43),touch.matches?390:355)*p.rail.length*(p.rail.length<.9?.88:1),width=height*p.imageWidth/p.imageHeight;
   node.style.left=(x-p.hook.x*width)+'px';node.style.top=(ropeY(x)-p.hook.y*height)+'px';node.style.setProperty('--piece-width',width+'px');node.style.setProperty('--piece-height',height+'px');node.style.setProperty('--hook-x',(p.hook.x*100)+'%');node.style.setProperty('--hook-y',(p.hook.y*100)+'%');node.style.zIndex=i===active?'12':String(2+i%3);node.style.visibility=x<-step*.7||x>w+step*.7?'hidden':'visible';const breeze=reduced.matches?0:Math.sin(motion.phase+i*.7)*.2;node.querySelector('.rail-rig').style.transform=`perspective(1200px) rotateY(${i===active?0:p.rail.angle}deg) rotateZ(${s.swing+breeze}deg) translateZ(${s.depth}px) scale(${s.scale})`;
  });const progress=((motion.offset/step)%pieces.length+pieces.length)%pieces.length;hero.querySelector('.rail-track i').style.transform=`translateX(${progress/(pieces.length-1)*65}px)`;
 }
 function spring(s,key,velocityKey,goal,dt,stiffness=150,damping=25){s[velocityKey]=(s[velocityKey]||0)+((goal-s[key])*stiffness-s[velocityKey]*damping)*dt;s[key]+=s[velocityKey]*dt;if(Math.abs(s[key]-goal)<.001&&Math.abs(s[velocityKey])<.002){s[key]=goal;s[velocityKey]=0;return false}return true}
 function animate(time){frame=0;const dt=last?Math.min((time-last)/1000,.03):1/60;last=time;let moving=false;states.forEach((s,i)=>{if(reduced.matches){s.swing=0;s.scale=i===active?1.06:1;s.depth=i===active?10:0;return;}moving=spring(s,'swing','velocity',0,dt,150,22)||moving;moving=spring(s,'scale','scaleVelocity',i===active?1.06:1,dt)||moving;moving=spring(s,'depth','depthVelocity',i===active?10:0,dt)||moving});paint();if(moving&&visible)frame=requestAnimationFrame(animate);else last=0;}
 function wake(){if(!frame&&visible)frame=requestAnimationFrame(animate)}
 function focus(index,impulse=1){if(active===index)return;active=index;hero.classList.toggle('has-focus',index>=0);nodes.forEach((node,i)=>node.classList.toggle('is-focused',i===index));if(index>=0){states[index].velocity+=impulse*4;keyIndex=index;nodes.forEach((node,i)=>node.tabIndex=i===index?0:-1);}wake();}
 function finishEntry(){entryFinished=true;const animation=entry;entry=null;if(animation){animation.progress(1);animation.kill();}if(window.gsap)gsap.set(camera,{clearProps:'transform,opacity'});}
 function move(direction){finishEntry();const next=Math.round(motion.offset/stepSize())+direction;keyIndex=((next+(touch.matches?0:5))%pieces.length+pieces.length)%pieces.length;if(window.gsap&&!reduced.matches)gsap.to(motion,{offset:next*stepSize(),duration:1.25,ease:cinematic,onUpdate:paint,overwrite:'auto'});else{motion.offset=next*stepSize();paint()}focus(keyIndex,direction);hero.querySelector('#rail-announcement').textContent=pieces[keyIndex].name+', '+money(pieces[keyIndex].price);}
 nodes.forEach((node,i)=>{node.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&!drag&&!showroom?.isOpen())focus(i,(e.movementX||1)>0?1:-1)});node.addEventListener('focus',()=>focus(i));node.addEventListener('click',()=>{if(suppress)return;finishEntry();focus(i);showroom?.open(pieces[i],node)});});
 scene.addEventListener('pointerleave',()=>{if(!drag)focus(-1);if(window.gsap){gsap.to(motion,{pan:0,duration:1.5,ease:'power3.out',onUpdate:paint,overwrite:'auto'});gsap.to(heading,{x:0,duration:1.8,ease:'power3.out'});}});
 scene.addEventListener('pointerdown',e=>{if(e.button!==0)return;finishEntry();drag={id:e.pointerId,x:e.clientX,start:motion.offset,moved:0};suppress=false;if(window.gsap)gsap.killTweensOf(motion,'offset,pan');});
 scene.addEventListener('pointermove',e=>{if(showroom?.isOpen())return;if(drag&&e.pointerId===drag.id){const dx=e.clientX-drag.x;drag.moved=Math.max(drag.moved,Math.abs(dx));if(drag.moved>7){scene.setPointerCapture(e.pointerId);hero.classList.add('is-dragging');suppress=true;motion.offset=drag.start-dx;focus(-1);states.forEach(s=>{s.swing=Math.max(-1,Math.min(1,dx*.006))});paint()}return;}if(e.pointerType!=='mouse'||reduced.matches||!window.gsap)return;const ratio=e.clientX/scene.clientWidth-.5;gsap.to(motion,{pan:-ratio*Math.min(160,scene.clientWidth*.12),duration:1.7,ease:'power3.out',onUpdate:paint,overwrite:'auto'});gsap.to(heading,{x:-ratio*8,duration:2,ease:'power3.out',overwrite:'auto'});});
 function release(e){if(!drag||e.pointerId!==drag.id)return;const moved=drag.moved>7;drag=null;hero.classList.remove('is-dragging');if(moved)wake();setTimeout(()=>suppress=false,0)}window.addEventListener('pointerup',release);scene.addEventListener('pointercancel',release);scene.addEventListener('lostpointercapture',release);
 scene.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}else if(e.key==='Enter'&&e.target===scene){e.preventDefault();showroom?.open(pieces[keyIndex],nodes[keyIndex])}});hero.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>move(Number(b.dataset.step)));
 new ResizeObserver(paint).observe(scene);new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible){wind?.resume();wake()}else wind?.pause()}).observe(hero);
 function ambient(){wind?.kill();motion.phase=0;if(window.gsap&&!reduced.matches)wind=gsap.to(motion,{phase:Math.PI*2,duration:18,repeat:-1,ease:'none',onUpdate:paint});paint();}ambient();reduced.addEventListener('change',()=>{finishEntry();ambient();wake()});
 showroom=window.initShowroom?.({hero,scene,nodes,focus,finishEntry,ease:cinematic,onOpen(){wind?.pause()},onClose(){if(visible)wind?.resume()}});paint();
 const ready=Promise.race([Promise.all([...rack.querySelectorAll('img')].slice(0,6).map(img=>img.decode().catch(()=>{}))),new Promise(r=>setTimeout(r,1800))]);
 if(window.gsap&&!reduced.matches){gsap.set(camera,{opacity:0});ready.then(()=>{if(entryFinished)return;const p=pieces[0],x=parseFloat(nodes[0].style.left)+parseFloat(nodes[0].style.getPropertyValue('--piece-width'))*p.hook.x,y=parseFloat(nodes[0].style.top)+parseFloat(nodes[0].style.getPropertyValue('--piece-height'))*p.hook.y;entry=gsap.timeline({onComplete(){entry=null;entryFinished=true}}).fromTo(camera,{scale:2.35,x:scene.clientWidth/2-x*2.35,y:scene.clientHeight*.16-y*2.35,opacity:1},{scale:1,x:0,y:0,opacity:1,duration:4.2,ease:cinematic,clearProps:'transform'}).fromTo(heading,{opacity:0,y:9},{opacity:1,y:0,duration:1.5,ease:'power3.out'},.8).fromTo(hero.querySelector('.rail-bottom'),{opacity:0},{opacity:1,duration:1},1.4);});}
};
